WITH purchasing_users AS (
  -- Users who recorded at least one “purchase” event in Nov‑2020
  SELECT DISTINCT user_pseudo_id
  FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_202011*`
  WHERE event_name = 'purchase'
),

page_views AS (
  -- Page‑view events generated by those purchasing users
  SELECT
    event_date,
    user_pseudo_id
  FROM `bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_202011*`
  WHERE event_name = 'page_view'
    AND user_pseudo_id IN (SELECT user_pseudo_id FROM purchasing_users)
)

SELECT
  event_date,
  COUNT(*) AS total_page_views,
  SAFE_DIVIDE(COUNT(*), COUNT(DISTINCT user_pseudo_id)) AS avg_page_views_per_user
FROM page_views
GROUP BY event_date
ORDER BY event_date;